def transform(g):
    H,W=len(g),len(g[0])
    bar=[r for r in range(H) if all(x==2 for x in g[r])][0]
    seen=[[False]*W for _ in range(H)]
    shapes=[]  # (color, cells)
    for r in range(H):
        for c in range(W):
            if g[r][c] and g[r][c]!=2 and not seen[r][c]:
                col=g[r][c]; stack=[(r,c)]; seen[r][c]=True; cells=[]
                while stack:
                    a,b=stack.pop(); cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and not seen[na][nb] and g[na][nb]==col:
                            seen[na][nb]=True; stack.append((na,nb))
                shapes.append((col,cells))
    d=-1 if bar==0 else 1
    pos=[list(c) for _,c in shapes]
    moved=True
    while moved:
        moved=False
        for i in range(len(shapes)):
            occ=set(t for j in range(len(shapes)) if j!=i for t in pos[j])
            if all(0<=a+d<H and (a+d,b) not in occ and a+d!=bar for a,b in pos[i]):
                pos[i]=[(a+d,b) for a,b in pos[i]]; moved=True
    out=[[0]*W for _ in range(H)]
    out[bar]=[2]*W
    for (col,_),cells in zip(shapes,pos):
        for a,b in cells: out[a][b]=col
    return out

